// types/quiz.ts
// Data contracts for the PMT EMS Exam Simulator (generated by `docmint` into public/data/exams/).

export interface ExamSummary {
  exam_id: string // e.g. "Y21-70"
  cohort: string // e.g. "Y20" | "Y21" | "Y22"
  title: string // e.g. "70% Tiêu hóa Y21"
  default_time_sec: number // e.g. 3600
  question_count: number
  group_counts: Record<string, number> // keys "1".."8"
  conflict_count: number
}

export interface SubjectManifest {
  subject: string // e.g. "tieu-hoa"
  subject_label: string // e.g. "Tiêu hóa"
  exams: ExamSummary[]
}

export interface ExamsManifest {
  updated_at: string
  subjects: SubjectManifest[]
}

export interface QuizOption {
  key: string // "A" | "B" | "C" | "D" (2..5 options handled gracefully)
  text: string
}

export type ExamGroupId = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8
export type ExamQuestionStatus = 'verified' | 'conflict' | 'ai_only'

export interface ExamQuestion {
  id: string // e.g. "Y21-70_Q38"
  exam_id: string
  cohort: string
  num: number
  group_id: ExamGroupId
  // 1: Giải phẫu, 2: Giải phẫu bệnh, 3: Mô phôi, 4: Sinh lý, 5: Sinh lý bệnh, 6: Dược lý, 7: Lâm sàng (Câu dài), 8: Hình ảnh
  group_name: string
  stem: string
  options: QuizOption[]
  answer: string // canonical option key
  status: ExamQuestionStatus
  legacy_key: string | null
  student_note: string | null
  hint: string
  formula_work: string | null
  textbook_excerpt: string | null
  explanation: string
  note_ref: string | null
  image: string | null // "assets/Y21-70_Q80_p12.png" -> `/data/exams/${subject}/${image}`
}

export interface SubjectQuestionBank {
  subject: string
  subject_label: string
  updated_at: string
  total_questions: number
  exams: ExamSummary[]
  questions: ExamQuestion[]
}

// ───────────────────────── Session / UI types ─────────────────────────

export type ExamMode = 'practice' | 'exam'
export type ReviewFilter = 'all' | 'wrong' | 'conflict'
export type PaletteItemState = 'unanswered' | 'answered' | 'correct' | 'incorrect'

/** Query-string contract between ExamCheckInDialog and app/pages/exams/[id].vue */
export interface ExamFilterQuery {
  mode: ExamMode
  exam: string // "all" | exam_id
  group: string // "all" | "1".."8"
  conflict: '0' | '1'
  shuffle: '0' | '1'
  time: string // minutes (string from URL); empty => auto
  name: string
  mssv: string
}

/** An option as displayed. `key` is ALWAYS the canonical key used for grading; `label` is the letter shown to the user. */
export interface DisplayOption {
  key: string
  text: string
  label: string
}

export interface PreparedQuestion extends ExamQuestion {
  displayOptions: DisplayOption[]
  displayAnswerLabel: string
}

export interface ExamScoreSummary {
  correctCount: number
  totalCount: number
  answeredCount: number
  percentage: number // 0..100, one decimal
  elapsedSec: number
}

export interface ExamPaletteItem {
  id: string
  no: number // 1-based position in the full session
  state: PaletteItemState
  flagged: boolean
  current: boolean
}

export interface ExamHistoryRecord {
  key: string // `${subject}|${exam}|${group}|${conflict}`
  subject: string
  exam: string
  group: string
  conflict: '0' | '1'
  mode: ExamMode
  correctCount: number
  totalCount: number
  percentage: number
  elapsedSec: number
  finishedAt: string // ISO
}
